class Solution:
    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:
        m, n = len(s1), len(s2)
        if m + n != len(s3):
            return False
        dp = [False] * (n + 1)                   # dp[j]: s3[:i+j] interleaves s1[:i] and s2[:j]
        for i in range(m + 1):
            for j in range(n + 1):
                if i == 0 and j == 0:
                    dp[j] = True
                    continue
                ok = False
                if i > 0 and dp[j] and s1[i - 1] == s3[i + j - 1]:        # take from s1
                    ok = True
                if j > 0 and dp[j - 1] and s2[j - 1] == s3[i + j - 1]:    # take from s2
                    ok = True
                dp[j] = ok
        return dp[n]
